    private Grid RenderDashboard()
    {
        var root = new Grid { Margin = new Thickness(0, 4, 0, 0) };
        root.RowDefinitions.Add(new RowDefinition { Height = new GridLength(DashboardPanelHeight) }); root.RowDefinitions.Add(new RowDefinition { Height = new GridLength(DashboardPanelHeight) }); root.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
        var top = new Grid(); AddStarColumns(top, 3); BuildCurrentInstalledPanel(top, 0); BuildFreeBrandLogo(top, 1); BuildTeamSpeakPanel(top, 2); Grid.SetRow(top, 0); root.Children.Add(top);
        var actions = new Grid(); AddStarColumns(actions, 3); AddDashboardTile(actions, 0, "switch", IsGerman ? "YACA WECHSELN" : "SWITCH YACA", IsGerman ? "Version auswählen\nund wechseln" : "Select a version\nand switch", (Brush)FindResource("AccentBrush"), () => ShowSwitchPage()); AddDashboardTile(actions, 1, "backup", IsGerman ? "BACKUP ERSTELLEN" : "CREATE BACKUP", IsGerman ? "Aktuelle Version sichern" : "Save current version", (Brush)FindResource("GoldBrush"), CreateBackupFromDashboard); AddDashboardTile(actions, 2, "updater", "YACA UPDATER", IsGerman ? "Neueste DLL prüfen\nund herunterladen" : "Check and download\nlatest DLL", (Brush)FindResource("AccentBrush"), () => ShowSwitchPage(IsGerman ? "YACA Updater: Download-Bereich geöffnet." : "YACA Updater: download area opened.")); Grid.SetRow(actions, 1); root.Children.Add(actions);
        var lower = new Grid(); AddStarColumns(lower, 2); BuildLatestBackupPanel(lower, 0); BuildAvailableVersionsPanel(lower, 1); Grid.SetRow(lower, 2); root.Children.Add(lower); return root;
    }

    private Border CreatePanelCard(Brush borderBrush) => new() { Background = (Brush)FindResource("SurfaceBrush"), BorderBrush = borderBrush, BorderThickness = new Thickness(1), CornerRadius = new CornerRadius(10), Padding = new Thickness(20), Margin = new Thickness(6) };

    private void BuildCurrentInstalledPanel(Grid host, int column)
    {
        var gold = (Brush)FindResource("GoldBrush"); var card = CreatePanelCard(gold); _currentCard = card; var panel = new Grid(); panel.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto }); panel.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) }); panel.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto }); var header = CreateDashboardHeader("shield", IsGerman ? "AKTUELL INSTALLIERT" : "CURRENTLY INSTALLED", gold); Grid.SetRow(header, 0); panel.Children.Add(header);
        var center = new StackPanel { HorizontalAlignment = HorizontalAlignment.Center, VerticalAlignment = VerticalAlignment.Center }; _currentValue = new TextBlock { Text = "—", FontSize = DashboardVersionFontSize, FontWeight = FontWeights.SemiBold, HorizontalAlignment = HorizontalAlignment.Center, TextAlignment = TextAlignment.Center, Foreground = (Brush)FindResource("ForegroundBrush") }; center.Children.Add(_currentValue); center.Children.Add(new Border { Background = (Brush)FindResource("SuccessBrush"), CornerRadius = new CornerRadius(4), Padding = new Thickness(16, 5, 16, 5), Margin = new Thickness(0, 8, 0, 0), HorizontalAlignment = HorizontalAlignment.Center, Child = new TextBlock { Text = IsGerman ? "AKTIV" : "ACTIVE", Foreground = Brushes.Black, FontSize = DashboardBadgeFontSize, FontWeight = FontWeights.Bold, TextAlignment = TextAlignment.Center } }); Grid.SetRow(center, 1); panel.Children.Add(center);
        _currentDetails = new TextBlock { FontSize = 13, LineHeight = 20, Foreground = (Brush)FindResource("ForegroundBrush"), TextAlignment = TextAlignment.Left, HorizontalAlignment = HorizontalAlignment.Left, VerticalAlignment = VerticalAlignment.Bottom, Margin = new Thickness(0, 8, 0, 0), TextWrapping = TextWrapping.NoWrap }; Grid.SetRow(_currentDetails, 2); panel.Children.Add(_currentDetails); card.Child = panel; Grid.SetColumn(card, column); host.Children.Add(card);
    }

    private static void BuildFreeBrandLogo(Grid host, int column) { var logo = new Image { Source = LoadLogo(), Width = 260, Height = 260, Stretch = Stretch.Uniform, HorizontalAlignment = HorizontalAlignment.Center, VerticalAlignment = VerticalAlignment.Center, IsHitTestVisible = false }; Grid.SetColumn(logo, column); host.Children.Add(logo); }

    private void BuildTeamSpeakPanel(Grid host, int column)
    {
        var gold = (Brush)FindResource("GoldBrush"); var card = CreatePanelCard(gold); var panel = new Grid(); panel.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto }); panel.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) }); panel.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto }); var header = CreateDashboardHeader("teamspeak", "STATUS", gold); Grid.SetRow(header, 0); panel.Children.Add(header);
        var center = new StackPanel { HorizontalAlignment = HorizontalAlignment.Center, VerticalAlignment = VerticalAlignment.Center }; _tsStatus = new TextBlock { Text = "—", FontSize = 28, FontWeight = FontWeights.SemiBold, HorizontalAlignment = HorizontalAlignment.Center, Foreground = gold }; _tsDescription = new TextBlock { FontSize = 14, Foreground = (Brush)FindResource("SecondaryBrush"), TextWrapping = TextWrapping.NoWrap, TextAlignment = TextAlignment.Center, Margin = new Thickness(0, 10, 0, 0), MaxWidth = 420 }; center.Children.Add(_tsStatus); center.Children.Add(_tsDescription); Grid.SetRow(center, 1); panel.Children.Add(center);
        _tsClose = new Button { Content = IsGerman ? "TeamSpeak 3 schließen" : "Close TeamSpeak 3", Visibility = Visibility.Collapsed, Background = (Brush)FindResource("ErrorBrush"), Foreground = Brushes.White, BorderBrush = (Brush)FindResource("ErrorBrush"), BorderThickness = new Thickness(0), Padding = new Thickness(18, 8, 18, 8), HorizontalAlignment = HorizontalAlignment.Center, Margin = new Thickness(0, 8, 0, 0), Cursor = System.Windows.Input.Cursors.Hand, FontSize = 17, FontWeight = FontWeights.Bold }; _tsClose.Template = CreateSquareButtonTemplate(); _tsClose.Click += (_, _) => CloseTeamSpeak(); Grid.SetRow(_tsClose, 2); panel.Children.Add(_tsClose); card.Child = panel; Grid.SetColumn(card, column); host.Children.Add(card);
    }

    private void BuildAvailableVersionsPanel(Grid host, int column)
    {
        var purple = (Brush)FindResource("AccentBrush"); var card = CreatePanelCard(purple); var panel = new Grid(); panel.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto }); panel.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) }); panel.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto }); var header = CreateDashboardHeader("backups", IsGerman ? "VERFÜGBARE VERSIONEN" : "AVAILABLE VERSIONS", purple); Grid.SetRow(header, 0); panel.Children.Add(header); _versionList = new StackPanel { Margin = new Thickness(6, 10, 6, 8) }; Grid.SetRow(_versionList, 1); panel.Children.Add(_versionList);
        var footer = new Grid { Margin = new Thickness(6, 0, 6, 2), Cursor = System.Windows.Input.Cursors.Hand, Background = Brushes.Transparent, HorizontalAlignment = HorizontalAlignment.Stretch }; footer.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) }); footer.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto }); var footerText = new TextBlock { Text = "0", FontSize = DashboardFooterFontSize, Foreground = purple, Background = Brushes.Transparent, HorizontalAlignment = HorizontalAlignment.Left, VerticalAlignment = VerticalAlignment.Center, Padding = new Thickness(8, 4, 8, 4), IsHitTestVisible = false }; Grid.SetColumn(footerText, 0); footer.Children.Add(footerText); var footerArrow = new System.Windows.Shapes.Path { Data = Geometry.Parse("M 2 2 L 8 8 L 2 14"), Stroke = purple, StrokeThickness = 2.2, Fill = Brushes.Transparent, Width = 18, Height = 18, Stretch = Stretch.Uniform, HorizontalAlignment = HorizontalAlignment.Right, VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(8, 0, 8, 0), IsHitTestVisible = false }; Grid.SetColumn(footerArrow, 1); footer.Children.Add(footerArrow); footer.MouseLeftButtonUp += (_, _) => ShowSwitchPage(); Grid.SetRow(footer, 2); panel.Children.Add(footer); card.Child = panel; Grid.SetColumn(card, column); host.Children.Add(card); _versionsFooterText = footerText;
    }

    private Grid CreateDashboardHeader(string iconKey, string text, Brush? headerBrush = null)
    {
        var brush = headerBrush ?? (Brush)FindResource("AccentBrush"); var header = new Grid { VerticalAlignment = VerticalAlignment.Center }; header.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto }); header.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto }); var content = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = VerticalAlignment.Center };
        if (iconKey.Equals("teamspeak", StringComparison.OrdinalIgnoreCase)) { var tsGroup = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = VerticalAlignment.Center }; var tsGeometry = new GeometryGroup { FillRule = FillRule.EvenOdd }; foreach (var pathData in TeamSpeakIconPaths) tsGeometry.Children.Add(Geometry.Parse(pathData)); tsGroup.Children.Add(new System.Windows.Shapes.Path { Data = tsGeometry, Fill = brush, Width = DashboardHeaderIconSize, Height = DashboardHeaderIconSize, Stretch = Stretch.Uniform, VerticalAlignment = VerticalAlignment.Center }); tsGroup.Children.Add(new TextBlock { Text = "TEAMSPEAK", FontSize = 10.5, FontWeight = FontWeights.Bold, Foreground = brush, VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(5, 0, 0, 0) }); content.Children.Add(tsGroup); }
        else if (DashboardIconData.TryGetValue(iconKey, out var data)) content.Children.Add(CreateIcon(data, brush, DashboardHeaderIconSize, DashboardHeaderIconSize, 0));
        content.Children.Add(new TextBlock { Text = text, FontSize = DashboardHeaderFontSize, FontWeight = FontWeights.SemiBold, Foreground = brush, VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(10, 0, 0, 0) }); Grid.SetRow(content, 0); header.Children.Add(content); var separator = new Border { Height = 1, Background = brush, Opacity = 0.65, Margin = new Thickness(0, 8, 0, 0), HorizontalAlignment = HorizontalAlignment.Stretch }; Grid.SetRow(separator, 1); header.Children.Add(separator); return header;
    }

    private void AddDashboardTile(Grid host, int column, string iconKey, string title, string subtitle, Brush accent, Action action)
    {
        var button = new Button { Style = (Style)FindResource("TileButtonStyle"), BorderBrush = accent, Margin = new Thickness(6) }; var panel = new StackPanel { HorizontalAlignment = HorizontalAlignment.Center, VerticalAlignment = VerticalAlignment.Center }; if (DashboardIconData.TryGetValue(iconKey, out var data)) panel.Children.Add(CreateIcon(data, accent, DashboardTileIconSize, DashboardTileIconSize, 0)); panel.Children.Add(new TextBlock { Text = title, FontSize = DashboardTileTitleFontSize, FontWeight = FontWeights.Bold, HorizontalAlignment = HorizontalAlignment.Center, Margin = new Thickness(0, 8, 0, 4) }); panel.Children.Add(new TextBlock { Text = subtitle, FontSize = DashboardTileSubtitleFontSize, Foreground = (Brush)FindResource("SecondaryBrush"), TextAlignment = TextAlignment.Center, TextWrapping = TextWrapping.NoWrap }); button.Content = panel; button.Click += (_, _) => action(); Grid.SetColumn(button, column); host.Children.Add(button);
    }

    private void BuildLatestBackupPanel(Grid host, int column)
    {
        var purple = (Brush)FindResource("AccentBrush"); var card = CreatePanelCard(purple); _backupCard = card; var panel = new Grid(); panel.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto }); panel.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) }); var header = CreateDashboardHeader("backup", IsGerman ? "LETZTES BACKUP" : "LATEST BACKUP"); Grid.SetRow(header, 0); panel.Children.Add(header);
        var content = new Grid { Margin = new Thickness(6, 16, 6, 0) }; content.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) }); content.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(160) }); _backupSummary = new TextBlock { FontSize = 15, LineHeight = 22, Foreground = (Brush)FindResource("ForegroundBrush"), TextWrapping = TextWrapping.NoWrap, VerticalAlignment = VerticalAlignment.Top, HorizontalAlignment = HorizontalAlignment.Left, TextAlignment = TextAlignment.Left, Margin = new Thickness(0, 0, 10, 0) }; Grid.SetColumn(_backupSummary, 0); content.Children.Add(_backupSummary); var backupIcon = CreateIcon(DashboardIconData["backup"], purple, 132, 132, 0); Grid.SetColumn(backupIcon, 1); content.Children.Add(backupIcon); Grid.SetRow(content, 1); panel.Children.Add(content); card.Child = panel; Grid.SetColumn(card, column); host.Children.Add(card);
    }

    private SolidColorBrush GetVersionRowBackground(int index)
    { if (index % 2 == 0) return Brushes.Transparent; if (FindResource("AccentBrush") is SolidColorBrush accent) return new SolidColorBrush(Color.FromArgb(18, accent.Color.R, accent.Color.G, accent.Color.B)); return Brushes.Transparent; }

    private void RenderVersionList(YacaPluginInfo? current)
    {
        if (_versionList is null) return; _versionList.Children.Clear(); var ordered = _plugins.OrderByDescending(p => p.Version).ThenByDescending(p => p.Build).ToList(); for (var index = 0; index < ordered.Count; index++) { var plugin = ordered[index]; var row = new Border { Background = GetVersionRowBackground(index), CornerRadius = new CornerRadius(3), Padding = new Thickness(7, 2, 7, 2), Margin = new Thickness(0, 1, 0, 1) }; var grid = new Grid { MinHeight = 34 }; grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) }); grid.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto }); grid.Children.Add(new TextBlock { Text = $"YACA {plugin.Version} - (Build: {plugin.Build?.ToString(CultureInfo.InvariantCulture) ?? "—"})", FontSize = DashboardVersionListFontSize, FontWeight = FontWeights.SemiBold, VerticalAlignment = VerticalAlignment.Center }); if (current?.Sha256.Equals(plugin.Sha256, StringComparison.OrdinalIgnoreCase) == true) { var badge = new Border { Background = (Brush)FindResource("SuccessBrush"), CornerRadius = new CornerRadius(4), Padding = new Thickness(7, 2, 7, 2), VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(10, 0, 0, 0), Child = new TextBlock { Text = IsGerman ? "INSTALLIERT" : "INSTALLED", Foreground = Brushes.Black, FontSize = 10, FontWeight = FontWeights.Bold } }; Grid.SetColumn(badge, 1); grid.Children.Add(badge); } row.Child = grid; _versionList.Children.Add(row); } if (_versionsFooterText is not null) _versionsFooterText.Text = IsGerman ? $"{_plugins.Count.ToString(CultureInfo.InvariantCulture)} Version(en) verfügbar" : $"{_plugins.Count.ToString(CultureInfo.InvariantCulture)} version(s) available";
    }

    private void UpdateBackupSummary(BackupInfo? backup)
    {
        if (_backupSummary is null) return; _backupSummary.Inlines.Clear(); if (backup is null) { _backupSummary.Inlines.Add(new Run(Texts.NoBackups)); return; }
        var versionText = backup.DisplayName.Split(" - ", 2, StringSplitOptions.None)[0]; var statusText = backup.IsAutomatic ? (IsGerman ? "Automatisches Backup" : "Automatic Backup") : (IsGerman ? "Manuelles Backup" : "Manual Backup"); var buildText = backup.SourceBuild?.ToString(CultureInfo.InvariantCulture) ?? "—"; var sizeBytes = backup.FileSize; var sizeMb = sizeBytes / 1024d / 1024d;
        _backupSummary.Inlines.Add(new Run($"{backup.Timestamp:dd.MM.yyyy HH:mm}") { FontSize = 34, FontWeight = FontWeights.SemiBold, Foreground = (Brush)FindResource("GoldBrush") }); _backupSummary.Inlines.Add(new LineBreak()); _backupSummary.Inlines.Add(new Run(" ") { FontSize = 8 }); _backupSummary.Inlines.Add(new LineBreak()); _backupSummary.Inlines.Add(new Run($"{versionText} • (Build: {buildText})") { FontSize = 20, FontWeight = FontWeights.SemiBold, Foreground = (Brush)FindResource("ForegroundBrush") }); _backupSummary.Inlines.Add(new LineBreak()); _backupSummary.Inlines.Add(new Run(" ") { FontSize = 8 }); _backupSummary.Inlines.Add(new LineBreak()); _backupSummary.Inlines.Add(new Run($"Status: {statusText}") { FontSize = 16, FontWeight = FontWeights.SemiBold, Foreground = (Brush)FindResource("ForegroundBrush") }); _backupSummary.Inlines.Add(new LineBreak()); _backupSummary.Inlines.Add(new Run($"Größe: {sizeMb:0.00} MB ({sizeBytes.ToString("N0", CultureInfo.GetCultureInfo("de-DE"))} Bytes)") { FontSize = 15, Foreground = (Brush)FindResource("ForegroundBrush") });
    }

    private static ControlTemplate CreateSquareButtonTemplate() { var template = new ControlTemplate(typeof(Button)); var border = new FrameworkElementFactory(typeof(Border)); border.SetValue(Border.BackgroundProperty, new TemplateBindingExtension(Button.BackgroundProperty)); border.SetValue(Border.BorderBrushProperty, new TemplateBindingExtension(Button.BorderBrushProperty)); border.SetValue(Border.BorderThicknessProperty, new TemplateBindingExtension(Button.BorderThicknessProperty)); border.SetValue(Border.CornerRadiusProperty, new CornerRadius(0)); var presenter = new FrameworkElementFactory(typeof(ContentPresenter)); presenter.SetValue(ContentPresenter.HorizontalAlignmentProperty, HorizontalAlignment.Center); presenter.SetValue(ContentPresenter.VerticalAlignmentProperty, VerticalAlignment.Center); presenter.SetValue(ContentPresenter.MarginProperty, new TemplateBindingExtension(Button.PaddingProperty)); border.AppendChild(presenter); template.VisualTree = border; return template; }
    private static void AddStarColumns(Grid grid, int count) { for (var i = 0; i < count; i++) grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) }); }
    private static System.Windows.Shapes.Path CreateIcon(string data, Brush fill, double width, double height, double _) => new() { Data = Geometry.Parse(data), Fill = fill, Stroke = null, Width = width, Height = height, Stretch = Stretch.Uniform, HorizontalAlignment = HorizontalAlignment.Center, VerticalAlignment = VerticalAlignment.Center };
    private static BitmapImage LoadLogo() => new(new Uri("pack://application:,,,/YacaPluginSwitcher;component/Assets/yaca_logo.png"));
